     return uploadFileFeishuInternal(...);
   }

   // 3. 如果是中文文件名：
   //    - 创建临时英文文件副本
   //    - 使用副本上传（避免 form-data 编码问题）
   //    - 但 file_name 参数仍使用原始中文名（用户看到中文）
