       file: tempPath,      // 临时英文路径（避免编码问题）
       fileName: fileName,  // 原始中文名（用户可见）
       ...
     });
   } finally {
     await unlink(tempPath); // 清理临时文件
   }
   ```

3. **验证修复**：
   ```bash
   # 检查修改是否正确
   grep -A 20 \"needsWorkaround\" /usr/lib/node_modules/openclaw/extensions/feishu/src/media.ts
   ```

4. **重启 OpenClaw**（如果需要）：
   ```bash
   openclaw gateway restart
   ```

---

## 替代方案（如果方案 1 不适用）

如果修改核心文件不方便，可以在发送文件前先重命名：

```typescript
// 在发送文件前使用
const tempEnglishName = `report_${Date.now()}.txt`;
await copyFile('2026-03-13-日报.txt', tempEnglishName);
await sendFile(tempEnglishName); // 发送英文文件名
await unlink(tempEnglishName);   // 清理
```

